contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that tests that sudicideAnyone either leaves c.balance unchanged on revert,
    // or sets c.balance to zero on success. We take a dummy uint param to provide input space.
    function run(uint256 dummy) public payable {
        require(true);

        uint256 beforeC = address(c).balance;

        bool reverted;
        // top-level state-changing call
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterC = address(c).balance;

        // General rule: either the call reverted and c's balance is unchanged, or it succeeded and c.balance == 0
        assert((reverted && afterC == beforeC) || (!reverted && afterC == 0));
    }

    receive() external payable { }
}

