// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 dummy) internal {
        vm.assume(true);
        uint256 beforeC = address(c).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterC = address(c).balance;
        assertTrue((reverted && afterC == beforeC) || (!reverted && afterC == 0));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable { }
}
